def _write_mini_tsp(tmp_path: Path, name: str = "mini4") -> Path:
    """Create a valid 4-city unit-square TSPLIB file for deterministic tests."""
    content = (
        f"NAME: {name}\n"
        "TYPE: TSP\n"
        "DIMENSION: 4\n"
        "EDGE_WEIGHT_TYPE: EUC_2D\n"
        "NODE_COORD_SECTION\n"
        "1 0.0 0.0\n"
        "2 3.0 0.0\n"
        "3 3.0 4.0\n"
        "4 0.0 4.0\n"
        "EOF\n"
    )
    tsp_file = tmp_path / f"{name}.tsp"
    tsp_file.write_text(content, encoding="utf-8")
    return tsp_file


