class TestSymmetricTSP:
    def test_euc_2d_half_up_rounding_and_symmetry(self, tmp_path):
        tsp_file = _write_mini_tsp(tmp_path)
        tsp = SymmetricTSP(seed=45, path_data=str(tsp_file), strategy=REVERSE)

        assert tsp.euclidean_dist([0.0, 0.0], [0.0, 0.0]) == 0
        # Exact .5 values must round half-up via floor(d + 0.5)
        assert tsp.euclidean_dist([0.0, 0.0], [1.5, 0.0]) == 2
        assert tsp.euclidean_dist([0.0, 0.0], [2.5, 0.0]) == 3
        assert tsp.euclidean_dist([0.0, 0.0], [2.49, 0.0]) == 2
        assert tsp.euclidean_dist([0.0, 0.0], [3.0, 4.0]) == 5

        # Distance matrix is symmetric with zero diagonal
        n = len(tsp.distance_matrix)
        assert n == 4
        for i in range(n):
            assert tsp.distance_matrix[i][i] == 0
            for j in range(n):
                assert tsp.distance_matrix[i][j] == tsp.distance_matrix[j][i]

    def test_evaluate_includes_return_leg_to_city_one(self, tmp_path):
        tsp_file = _write_mini_tsp(tmp_path)
        tsp = SymmetricTSP(seed=45, path_data=str(tsp_file), strategy=SWAP)

        # Perimeter of 3x4 rectangle: 3 + 4 + 3 + 4 = 14
        assert tsp.evaluate([1, 2, 3, 4]) == 14
        # Diagonal crossing: 1->3 (5) + 3->2 (4) + 2->4 (5) + 4->1 (4) = 18
        assert tsp.evaluate([1, 3, 2, 4]) == 18

    def test_initialise_scout_fixes_city_one_and_is_deterministic(self):
        tsp_a = SymmetricTSP(seed=45, path_data=EIL51_CONFIG.path, strategy=REVERSE)
        tsp_b = SymmetricTSP(seed=45, path_data=EIL51_CONFIG.path, strategy=REVERSE)

        tour_a = tsp_a.initialise_scout()
        tour_b = tsp_b.initialise_scout()

        assert tour_a == tour_b
        assert tour_a[0] == 1
        assert len(tour_a) == EIL51_CONFIG.cities
        assert set(tour_a) == set(range(1, EIL51_CONFIG.cities + 1))

    @pytest.mark.parametrize("strategy", [SWAP, REVERSE])
    def test_get_neighbour_preserves_city_one_permutation_and_immutability(
        self, strategy
    ):
        tsp = SymmetricTSP(seed=45, path_data=EIL51_CONFIG.path, strategy=strategy)
        original = tsp.initialise_scout()
        original_copy = list(original)
        bee = Bee(original, tsp.evaluate(original), patch_size=1.0)

        for _ in range(30):
            neighbour = tsp.get_neighbour(bee)
            assert bee.site == original_copy
            assert neighbour[0] == 1
            assert len(neighbour) == EIL51_CONFIG.cities
            assert set(neighbour) == set(range(1, EIL51_CONFIG.cities + 1))
            assert neighbour != original_copy

    def test_swap_changes_exactly_two_movable_positions(self):
        tsp = SymmetricTSP(seed=45, path_data=EIL51_CONFIG.path, strategy=SWAP)
        base = list(range(1, EIL51_CONFIG.cities + 1))
        bee = Bee(base, tsp.evaluate(base), patch_size=1.0)

        for _ in range(25):
            neighbour = tsp.get_neighbour(bee)
            diff = [idx for idx, (a, b) in enumerate(zip(base, neighbour)) if a != b]
            assert len(diff) == 2
            i, j = diff
            assert 1 <= i < j <= len(base) - 1
            assert neighbour[i] == base[j] and neighbour[j] == base[i]

    def test_reverse_inverts_contiguous_segment_and_respects_patch_size(self):
        tsp = SymmetricTSP(seed=45, path_data=EIL51_CONFIG.path, strategy=REVERSE)
        base = list(range(1, EIL51_CONFIG.cities + 1))

        # Very small patch_size must cap max_span to 1 (adjacent reversal)
        small_bee = Bee(base, tsp.evaluate(base), patch_size=1e-4)
        for _ in range(25):
            neighbour = tsp.get_neighbour(small_bee)
            diff = [idx for idx, (a, b) in enumerate(zip(base, neighbour)) if a != b]
            assert len(diff) == 2
            assert diff[1] - diff[0] == 1
            assert diff[0] >= 1

        # Full patch_size reverses a contiguous slice route[i : j + 1]
        full_bee = Bee(base, tsp.evaluate(base), patch_size=1.0)
        for _ in range(25):
            neighbour = tsp.get_neighbour(full_bee)
            diff = [idx for idx, (a, b) in enumerate(zip(base, neighbour)) if a != b]
            i, j = diff[0], diff[-1]
            assert 1 <= i < j <= len(base) - 1
            expected = base[:i] + list(reversed(base[i : j + 1])) + base[j + 1 :]
            assert neighbour == expected

    def test_invalid_strategy_raises(self, tmp_path):
        tsp_file = _write_mini_tsp(tmp_path)
        tsp = SymmetricTSP(seed=45, path_data=str(tsp_file), strategy="INVALID")
        bee = Bee([1, 2, 3, 4], 14, patch_size=1.0)
        with pytest.raises(ValueError, match="Invalid strategy"):
            tsp.get_neighbour(bee)


