class TestContinuousFunctionOptimisation:
    def test_initialise_scout_dimension_bounds_and_determinism(self):
        p1 = ContinuousFunctionOptimisation(45, -5.12, 5.12, 10, sphere)
        p2 = ContinuousFunctionOptimisation(45, -5.12, 5.12, 10, sphere)

        v1 = p1.initialise_scout()
        v2 = p2.initialise_scout()

        assert v1 == v2
        assert len(v1) == 10
        assert all(-5.12 <= x <= 5.12 for x in v1)
        assert math.isclose(p1.evaluate(v1), sphere(v1), rel_tol=1e-12)

    def test_get_neighbour_clips_to_bounds_and_respects_patch_size(self):
        lower, upper = -5.0, 10.0
        problem = ContinuousFunctionOptimisation(45, lower, upper, 10, sphere)

        # Boundary vector tests clipping on both lower and upper ends
        boundary_vec = [lower] * 5 + [upper] * 5
        boundary_copy = list(boundary_vec)
        bee = Bee(boundary_vec, problem.evaluate(boundary_vec), patch_size=0.5)

        for _ in range(50):
            neighbour = problem.get_neighbour(bee)
            assert bee.site == boundary_copy
            assert len(neighbour) == 10
            assert all(lower <= x <= upper for x in neighbour)

        # Interior vector verifies perturbation stays within +/- (upper - lower) * patch_size
        center = [2.5] * 10
        patch = 0.05
        max_delta = (upper - lower) * patch
        interior_bee = Bee(center, problem.evaluate(center), patch_size=patch)
        for _ in range(30):
            neighbour = problem.get_neighbour(interior_bee)
            assert all(abs(x - 2.5) <= max_delta + 1e-12 for x in neighbour)


