class _ScriptedProblem(OptimisationProblem):
    """Minimal deterministic problem to unit-test solver mechanics directly."""

    def __init__(self, scout_values, neighbour_sequence):
        self._scouts = iter(scout_values)
        self._neighbours = iter(neighbour_sequence)
        self.received_centers = []

    @property
    def problem_type(self):
        return "SCRIPTED"

    def initialise_scout(self):
        return [next(self._scouts)]

    def evaluate(self, solution):
        return float(solution[0])

    def get_neighbour(self, bee):
        self.received_centers.append(bee.site[0])
        return [next(self._neighbours)]


@dataclass(frozen=True)
class _SmallConfig:
    max_evaluations: int = 100
    ns: int = 4
    ne: int = 1
    nb: int = 2
    nre: int = 3
    nrb: int = 2
    stlim: int = 2
    ngh: float = 0.5
    shrink_factor: float = 0.8


class TestTrackedProblemAndSolver:
    def test_tracked_problem_enforces_exact_budget_and_monotonic_history(self):
        cfo = ContinuousFunctionOptimisation(45, -5.12, 5.12, 5, sphere)
        tracked = TrackedProblem(cfo, initial_population_size=5, max_evaluations=12)

        for _ in range(12):
            v = tracked.initialise_scout()
            tracked.evaluate(v)

        assert tracked.tracker.evaluations == 12
        assert tracked.tracker.initial_best is not None
        assert len(tracked.tracker.history) == 12
        assert all(
            tracked.tracker.history[i] >= tracked.tracker.history[i + 1]
            for i in range(11)
        )

        # Next evaluation must raise BudgetExhausted without incrementing evaluations
        with pytest.raises(BudgetExhausted):
            tracked.evaluate(tracked.initialise_scout())
        assert tracked.tracker.evaluations == 12

    def test_solver_exploit_site_greedy_sequential_update_and_shrinking(self):
        cfg = _SmallConfig()
        # Recruits for improving site (start=10.0): 8.0 (improves -> center becomes 8.0),
        # 9.0 (rejected, center stays 8.0), 6.0 (improves -> center becomes 6.0)
        # Recruits for stagnating site (start=5.0): 6.0, 7.0 (neither improves -> shrink + stagnation)
        problem = _ScriptedProblem(
            scout_values=[],
            neighbour_sequence=[8.0, 9.0, 6.0, 6.0, 7.0],
        )
        solver = BeesAlgorithmSolver(problem, cfg)

        improving = Bee([10.0], 10.0, patch_size=0.5)
        improving.stagnation_count = 1
        solver.exploit_site([improving], recruit_count=3)
        assert improving.site == [6.0]
        assert improving.fitness == 6.0
        assert improving.stagnation_count == 0
        assert improving.patch_size == 0.5
        # Verifies greedy sequential center updates: 10.0 -> 8.0 -> 8.0
        assert problem.received_centers[:3] == [10.0, 8.0, 8.0]

        stagnating = Bee([5.0], 5.0, patch_size=0.5)
        solver.exploit_site([stagnating], recruit_count=2)
        assert stagnating.site == [5.0]
        assert stagnating.fitness == 5.0
        assert stagnating.stagnation_count == 1
        assert math.isclose(stagnating.patch_size, 0.5 * cfg.shrink_factor)

    def test_solver_rank_abandon_and_replenish(self):
        cfg = _SmallConfig()
        problem = _ScriptedProblem(
            scout_values=[20.0, 5.0, 15.0, 1.0, 30.0, 40.0, 50.0],
            neighbour_sequence=[],
        )
        solver = BeesAlgorithmSolver(problem, cfg)
        solver.initialise()
        assert len(solver.scouts) == cfg.ns

        elites, selected = solver.rank_and_split_sites()
        assert [b.fitness for b in elites] == [1.0]
        assert [b.fitness for b in selected] == [5.0]

        # Simulate stagnation on selected site reaching stlim=2
        selected[0].stagnation_count = cfg.stlim
        solver.scouts = elites + selected
        abandoned = solver.abandon_stagnated_sites()
        assert abandoned == 1
        assert len(solver.scouts) == 1

        solver.replenish_scouts((cfg.ns - cfg.nb) + abandoned)
        assert len(solver.scouts) == cfg.ns

    def test_end_to_end_tsp_incomplete_final_cycle_and_determinism(self):
        # Budget 350 is not aligned with TSPConfig cycle size (10 init + 147/cycle)
        budget = 350
        cfg = TSPConfig(max_evaluations=budget)

        def _run_once(seed: int):
            tsp = SymmetricTSP(seed, EIL51_CONFIG.path, REVERSE)
            tracked = TrackedProblem(tsp, cfg.ns, cfg.max_evaluations)
            solver = BeesAlgorithmSolver(tracked, cfg)
            with pytest.raises(BudgetExhausted):
                solver.run()
            return tsp, tracked.tracker

        tsp1, tr1 = _run_once(45)
        _, tr2 = _run_once(45)

        assert tr1.evaluations == budget
        assert len(tr1.history) == budget
        assert tr1.history == tr2.history
        assert tr1.best_solution.site == tr2.best_solution.site
        assert tr1.best_solution.fitness <= tr1.initial_best.fitness

        is_valid, errors = validate_tsp_tour(
            route=tr1.best_solution.site,
            city_coordinates=tsp1.city_coordinates,
            distance_matrix=tsp1.distance_matrix,
            reported_length=tr1.best_solution.fitness,
        )
        assert is_valid, f"Unexpected tour errors: {errors}"

    def test_end_to_end_continuous_incomplete_final_cycle_and_determinism(self):
        # Budget 250 is not aligned with FunctionOptimisationConfig cycle size
        budget = 250
        cfg = FunctionOptimisationConfig(max_evaluations=budget)

        def _run_once(seed: int):
            cfo = ContinuousFunctionOptimisation(
                seed,
                SPHERE_CONFIG.lower,
                SPHERE_CONFIG.upper,
                10,
                SPHERE_CONFIG.function,
            )
            tracked = TrackedProblem(cfo, cfg.ns, cfg.max_evaluations)
            solver = BeesAlgorithmSolver(tracked, cfg)
            with pytest.raises(BudgetExhausted):
                solver.run()
            return tracked.tracker

        tr1 = _run_once(45)
        tr2 = _run_once(45)

        assert tr1.evaluations == budget
        assert len(tr1.history) == budget
        assert tr1.history == tr2.history
        assert tr1.best_solution.site == tr2.best_solution.site
        assert tr1.best_solution.fitness <= tr1.initial_best.fitness

        is_valid, errors = validate_continuous_vector(
            vector=tr1.best_solution.site,
            dimension=10,
            lower=SPHERE_CONFIG.lower,
            upper=SPHERE_CONFIG.upper,
            func=SPHERE_CONFIG.function,
            reported_value=tr1.best_solution.fitness,
        )
        assert is_valid, f"Unexpected continuous errors: {errors}"


