class TestValidators:
    def test_validate_tsp_tour_valid_and_failure_cases(self, tmp_path):
        tsp_file = _write_mini_tsp(tmp_path)
        tsp = SymmetricTSP(45, str(tsp_file), REVERSE)

        ok, errs = validate_tsp_tour(
            [1, 2, 3, 4], tsp.city_coordinates, tsp.distance_matrix, 14
        )
        assert ok and errs == []

        ok, errs = validate_tsp_tour(None, tsp.city_coordinates)
        assert not ok and "Route is None" in errs[0]

        ok, errs = validate_tsp_tour([2, 1, 3, 4], tsp.city_coordinates)
        assert not ok and any("start at city 1" in e for e in errs)

        ok, errs = validate_tsp_tour([1, 2, 2, 4], tsp.city_coordinates)
        assert not ok and any("Missing cities" in e for e in errs)

        ok, errs = validate_tsp_tour([1, 2, 3], tsp.city_coordinates)
        assert not ok and any("Expected 4 cities" in e for e in errs)

        ok, errs = validate_tsp_tour(
            [1, 2, 3, 4], tsp.city_coordinates, tsp.distance_matrix, 999
        )
        assert not ok and any("does not match recomputed" in e for e in errs)

    def test_validate_continuous_vector_valid_and_failure_cases(self):
        ok, errs = validate_continuous_vector(
            [0.0, 1.0, -2.0], 3, -5.0, 5.0, sphere, 5.0
        )
        assert ok and errs == []

        ok, errs = validate_continuous_vector(None, 3, -5.0, 5.0)
        assert not ok and "None" in errs[0]

        ok, errs = validate_continuous_vector([0.0, 1.0], 3, -5.0, 5.0)
        assert not ok and any("Expected dimension 3" in e for e in errs)

        ok, errs = validate_continuous_vector([0.0, float("nan"), 1.0], 3, -5.0, 5.0)
        assert not ok and any("Non-finite coordinate" in e for e in errs)

        ok, errs = validate_continuous_vector([0.0, 5.5, 1.0], 3, -5.0, 5.0)
        assert not ok and any("out of bounds" in e for e in errs)

        ok, errs = validate_continuous_vector(
            [0.0, 1.0, -2.0], 3, -5.0, 5.0, sphere, 99.0
        )
        assert not ok and any("does not match recomputed" in e for e in errs)
